window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-154"]=[{"id":"set2-B7ufAllK","fingerprint":"e51372623bf5ffe0","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Care este mecanismul patogenic considerat în trecut pentru formarea chistului primordial?","options":[{"id":"A","text":"Rezultă prin transformarea chistică a epiteliului organului adamantin, după formarea coroanei dentare."},{"id":"B","text":"Apare ca urmare a unui proces inflamator periapical la un dinte devital."},{"id":"C","text":"Se formează prin degenerarea chistică a laminei dentare, după erupția completă a dintelui."},{"id":"D","text":"Rezultă prin degenerarea chistică a epiteliului organului adamantin, înaintea dezvoltării structurilor dure dentare."},{"id":"E","text":"Derivă din resturi epiteliale Malassez activate de un traumatism ocluzal."}],"correct":["D"],"pages":[636],"source":"set-2"},{"id":"set2-MDuY4Iqi","fingerprint":"1cdc1a54404460ba","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Ce relație există între dezvoltarea unui chist primordial și structura dentară adiacentă, conform conceptului istoric?","options":[{"id":"A","text":"Un chist primordial se dezvoltă în locul unui dinte."},{"id":"B","text":"Un chist primordial se dezvoltă întotdeauna la apexul unui dinte neerupt."},{"id":"C","text":"Un chist primordial apare doar după extracția unui dinte permanent."},{"id":"D","text":"Un chist primordial este o complicație a unui dinte supranumerar."},{"id":"E","text":"Un chist primordial se formează întotdeauna în jurul coroanei unui dinte inclus."}],"correct":["A"],"pages":[636],"source":"set-2"},{"id":"set2-1oN-jUVi","fingerprint":"23b317a90680abc5","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Referitor la terminologia utilizată pentru leziunile chistice odontogene, care afirmație este corectă?","options":[{"id":"A","text":"Termenii de chist primordial și keratochist odontogen nu au fost niciodată considerați sinonimi."},{"id":"B","text":"Clasificarea OMS din 1992 preferă termenul de chist primordial."},{"id":"C","text":"Clasificarea OMS din 1992 preferă termenul de keratochist odontogen."},{"id":"D","text":"Termenul de keratochist odontogen a fost complet înlocuit de cel de chist primordial în prezent."},{"id":"E","text":"Clasificarea OMS din 1972 a introdus pentru prima dată termenul de keratochist odontogen."}],"correct":["C"],"pages":[636],"source":"set-2"},{"id":"set2-XPVzrrJb","fingerprint":"9ac2f84273a61775","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Ce caracteristică specifică definește keratochistul odontogen primordial?","options":[{"id":"A","text":"Este o leziune care apare doar după finalizarea formării structurilor dure dentare."},{"id":"B","text":"Este o variantă a chistului dentiger."},{"id":"C","text":"Derivă exclusiv din lamina dentară, fără legătură cu dezvoltarea dentară."},{"id":"D","text":"Se dezvoltă în locul unui dinte."},{"id":"E","text":"Este sinonim cu chistul primordial descris în clasificarea OMS din 1972."}],"correct":["D"],"pages":[636],"source":"set-2"},{"id":"set2-8GfUXzHu","fingerprint":"87ae4496f3748e39","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Care este originea keratochistului odontogen primordial?","options":[{"id":"A","text":"Este o consecință a perforării peretelui unui chist dentiger."},{"id":"B","text":"Se dezvoltă din resturile Serres sau din celulele bazale ale epiteliului oral."},{"id":"C","text":"Derivă din epiteliul adamantin redus în jurul unui dinte neerupt."},{"id":"D","text":"Are un caracter recidivant mai redus comparativ cu forma dentigeră."},{"id":"E","text":"Apare prin creșterea presiunii osmotice în interiorul unei leziuni preexistente."}],"correct":["B"],"pages":[637],"source":"set-2"},{"id":"set2-6B_quYGH","fingerprint":"b24f77b31e164f1b","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care dintre următoarele afirmații referitoare la epidemiologia și caracteristicile keratochistului odontogen sunt adevărate?","options":[{"id":"A","text":"Reprezintă aproximativ 5-10% din totalul chisturilor odontogene."},{"id":"B","text":"Prezența keratochisturilor multiple la copii poate fi asociată cu sindromul nevic bazocelular (sindromul Gorlin)."},{"id":"C","text":"Mecanismul de creștere se bazează pe presiunea osmotică intrachistică, asemănător altor chisturi."},{"id":"D","text":"Localizarea predilectă este la maxilar, în dreptul caninului."},{"id":"E","text":"Apar cu precădere la sexul feminin, în special la vârstnici."}],"correct":["A","B"],"pages":[637],"source":"set-2"},{"id":"set2-COcVB9H2","fingerprint":"1178e84d4bea3c90","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Ce caracteristică clinică descrie cel mai bine evoluția unui keratochist odontogen?","options":[{"id":"A","text":"Provoacă o reacție inflamatorie minimă în țesuturile moi la perforarea peretelui chistic."},{"id":"B","text":"Sunt întotdeauna uniloculare și de dimensiuni mici."},{"id":"C","text":"Induce frecvent și precoce tulburări senzitive prin compresia nervului alveolar inferior."},{"id":"D","text":"Pe măsură ce evoluează, poate induce mobilitatea și resorbția rădăcinilor dinților adiacenți."},{"id":"E","text":"Se extinde cu predilecție în plan vestibulo-lingual, cauzând liza rapidă a osului cortical."}],"correct":["D"],"pages":[637],"source":"set-2"},{"id":"set2-7tkR7S5l","fingerprint":"c98858b5af1a157b","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Care aspect radiologic este sugestiv pentru un keratochist odontogen primordial?","options":[{"id":"A","text":"O leziune radioopacă, cu margini difuze, extinsă în țesuturile moi."},{"id":"B","text":"Prezența resorbției rădăcinilor dinților adiacenți, considerată un semn patognomonic."},{"id":"C","text":"O leziune radiotransparentă cu evidențierea unui dinte neerupt situat parțial intralezional."},{"id":"D","text":"Lipsa dintelui intralezional într-o imagine radiotransparentă cu limite nete."},{"id":"E","text":"Un aspect radiologic multilocular, întotdeauna imposibil de diferențiat de un chist rezidual."}],"correct":["D"],"pages":[637],"source":"set-2"},{"id":"set2-WDuUoz96","fingerprint":"b1a995c9a8ff4909","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care dintre următoarele entități patologice sunt incluse în diagnosticul diferențial al unui keratochist odontogen primordial multilocular?","options":[{"id":"A","text":"Tumora centrală cu celule gigante."},{"id":"B","text":"Chistul rezidual."},{"id":"C","text":"Ameloblastomul."},{"id":"D","text":"Mixomul odontogen."},{"id":"E","text":"Chistul parodontal lateral."}],"correct":["A","C","D"],"pages":[637],"source":"set-2"},{"id":"set2-RnqQUhkc","fingerprint":"d74b5588e0117be2","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Care este atitudinea terapeutică de primă intenție pentru un keratochist de dimensiuni relativ mici?","options":[{"id":"A","text":"Marsupializarea leziunii pentru a reduce presiunea internă."},{"id":"B","text":"Drenajul conținutului chistic și obturație de canal la dinții adiacenți."},{"id":"C","text":"Monitorizarea clinică și radiologică fără intervenție chirurgicală."},{"id":"D","text":"Chistectomia, cu îndepărtarea completă a membranei chistice."},{"id":"E","text":"Rezecția osoasă marginală sau segmentară."}],"correct":["D"],"pages":[637],"source":"set-2"},{"id":"set2-LxHnbGpQ","fingerprint":"3dfcab6f86064c98","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"În ce zone anatomice specifice se produce cu predilecție liza corticalelor osoase în evoluția tardivă a unui keratochist odontogen?","options":[{"id":"A","text":"La mandibulă, în zona laterală, liza osoasă apare spre vestibular."},{"id":"B","text":"Liza osoasă la nivelul corticalei apare precoce, indiferent de localizare."},{"id":"C","text":"La maxilar, liza corticalei se produce în special spre palatinal."},{"id":"D","text":"La mandibulă, în zona laterală, liza se produce spre lingual."},{"id":"E","text":"La mandibulă, în zona anterioară și premolară, liza se produce spre vestibular."}],"correct":["D","E"],"pages":[637],"source":"set-2"},{"id":"set2-Ku2C-ZQA","fingerprint":"2f90de34e7e09824","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt afirmațiile corecte cu privire la managementul chirurgical al unui keratochist odontogen?","options":[{"id":"A","text":"Menținerea dinților adiacenți este posibilă, condiționată de suportul osos restant și de realizarea unui chiuretaj atent al acestora."},{"id":"B","text":"Pachetul vasculo-nervos alveolar inferior este frecvent infiltrat și trebuie sacrificat în timpul intervenției."},{"id":"C","text":"Chistectomia este indicată ca primă intenție curativă pentru keratochisturile de dimensiuni relativ mici."},{"id":"D","text":"Pentru keratochisturile primordiale, se recomandă extirparea unei porțiuni de mucoasă alveolară hiperkeratinizată."},{"id":"E","text":"În cazul efracționării corticalei mandibulare, este necesară extirparea unei zone de țesut moale adiacent pentru a preveni invazia locală."}],"correct":["A","C","D"],"pages":[638],"source":"set-2"},{"id":"set2-aBDJE0aB","fingerprint":"5fde3fbc88f9b750","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"În ce situație clinică este indicată rezecția osoasă marginală sau segmentară pentru un keratochist?","options":[{"id":"A","text":"În cazul keratochisturilor primordiale de mici dimensiuni, ca primă intenție."},{"id":"B","text":"Pentru keratochisturile odontogene dentigere, cu scopul de a facilita erupția dintelui inclus."},{"id":"C","text":"Atunci când corticala osoasă este integră, pentru a preveni erodarea acesteia."},{"id":"D","text":"Când pachetul vasculo-nervos alveolar inferior este infiltrat de procesul chistic."},{"id":"E","text":"Atunci când leziunea este de mari dimensiuni și a erodat corticala osoasă."}],"correct":["E"],"pages":[638],"source":"set-2"},{"id":"set2-28K7nH09","fingerprint":"6c53a28a6f5634ea","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care dintre următorii factori sunt asociați cu un risc crescut de recidivă a keratochisturilor după tratament?","options":[{"id":"A","text":"Tratamentul prin rezecție osoasă segmentară."},{"id":"B","text":"Prezența unui keratochist odontogen primordial."},{"id":"C","text":"Leziunile multiloculare sau cele care au erodat corticalele osoase."},{"id":"D","text":"Tratamentul prin marsupializare."},{"id":"E","text":"Neîndepărtarea chistului monobloc."}],"correct":["B","C","D","E"],"pages":[638],"source":"set-2"},{"id":"set2-1wu0xZXO","fingerprint":"ba2bb25a1ce67fc7","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Unde este localizată specific atașarea unui chist folicular față de dintele neerupt asociat?","options":[{"id":"A","text":"La nivelul furcației rădăcinilor, în cazul dinților pluriradiculari."},{"id":"B","text":"La nivelul apexului radicular al dintelui."},{"id":"C","text":"La nivelul joncțiunii smalț-cement."},{"id":"D","text":"Pe suprafața ocluzală a coroanei dentare."},{"id":"E","text":"Pe întreaga suprafață a rădăcinii dentare."}],"correct":["C"],"pages":[638],"source":"set-2"},{"id":"set2-HL_eRR8W","fingerprint":"507ea92f54fabd52","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Conform teoriilor patogenice, cum se formează un chist folicular?","options":[{"id":"A","text":"Prin acumularea de conținut chistic între coroana dintelui și epiteliul adamantin redus."},{"id":"B","text":"Prin degenerarea chistică a organului smalțului după finalizarea amelogenezei."},{"id":"C","text":"Prin transformarea chistică a resturilor epiteliale Malassez din ligamentul parodontal."},{"id":"D","text":"Prin acumularea de lichid între stratul extern și cel intern al epiteliului adamantin redus."},{"id":"E","text":"Prin inflamația cronică a papilei dentare în timpul odontogenezei."}],"correct":["A","D"],"pages":[638],"source":"set-2"},{"id":"set2-swIPThVl","fingerprint":"e186c694d3e8c88f","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Ce entități patologice trebuie luate în considerare în diagnosticul diferențial al unei formațiuni de mari dimensiuni, cu aspect de chist dentiger, care deformează părțile moi?","options":[{"id":"A","text":"Un chist radicular suprainfectat de la un dinte adiacent."},{"id":"B","text":"Un chist osos anevrismal sau o displazie fibroasă."},{"id":"C","text":"Un chist folicular simplu de dimensiuni excepționale."},{"id":"D","text":"O suprainfectare a chistului folicular de la un proces periapical."},{"id":"E","text":"Un keratochist odontogen dentiger sau un ameloblastom."}],"correct":["E"],"pages":[638],"source":"set-2"},{"id":"set2-q-eaUgAx","fingerprint":"29bcd5c7f69f7baa","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt afirmațiile corecte despre epidemiologia și etiologia chistului folicular?","options":[{"id":"A","text":"Fenomenele repetate de pericoronarită ale unui dinte semiinclus pot contribui la formarea sa."},{"id":"B","text":"Afectează cel mai adesea persoanele în vârstă, fiind rar la adolescenți și tineri."},{"id":"C","text":"Reprezintă aproximativ 20% din totalul chisturilor de dezvoltare ale oaselor maxilare."},{"id":"D","text":"Procesele inflamatorii periapicale cronice ale unui dinte decidual pot fi un factor declanșator."},{"id":"E","text":"Cea mai frecventă localizare este la nivelul caninului superior inclus."}],"correct":["A","C","D"],"pages":[638],"source":"set-2"},{"id":"set2-fZkqzzXd","fingerprint":"4b29a5b2595e3cef","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Care este aspectul radiologic tipic al unui chist folicular de mici dimensiuni?","options":[{"id":"A","text":"O radiotransparență uniloculară, bine delimitată, care înconjoară coroana unui dinte inclus și se atașează la colet."},{"id":"B","text":"O radiotransparență multiloculară, cu contur difuz, atașată la apexul unui dinte inclus."},{"id":"C","text":"O imagine mixtă, radioopacă-radiotransparentă, localizată strict la nivelul bifurcației rădăcinilor unui dinte erupt."},{"id":"D","text":"Un chist care se extinde spre apical, nerespectând joncțiunea amelo-dentinară, și care poate circumscrie radiologic dintele."},{"id":"E","text":"O zonă radioopacă, cu limite șterse, care induce resorbția coroanei dintelui semiinclus."}],"correct":["A"],"pages":[639],"source":"set-2"},{"id":"set2-hwLv-hku","fingerprint":"e4e8a3bed7d4bfe3","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Ce variantă de chist folicular este descrisă ca o radiotransparență uniloculară suprapusă peste bifurcația rădăcinilor unui molar de minte inferior semiinclus?","options":[{"id":"A","text":"Chistul paradentar"},{"id":"B","text":"Varianta cu extensie linguală"},{"id":"C","text":"Varianta „circumferențială”"},{"id":"D","text":"Varianta cu extensie laterală"},{"id":"E","text":"Chistul vestibular de bifurcație"}],"correct":["A","E"],"pages":[639],"source":"set-2"},{"id":"set2-SkhsYLEY","fingerprint":"fda6e2656000f5ae","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care dintre următoarele afecțiuni sunt incluse în diagnosticul diferențial al chistului folicular?","options":[{"id":"A","text":"Chistul radicular"},{"id":"B","text":"Ameloblastomul"},{"id":"C","text":"Carcinomul spinocelular"},{"id":"D","text":"Tumora odontogenă adenomatoidă, pentru localizări anterioare"},{"id":"E","text":"Fibromul ameloblastic"}],"correct":["B","D","E"],"pages":[639],"source":"set-2"},{"id":"set2-Wn8zf1XY","fingerprint":"83395f63442c5fba","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Ce reprezintă tratamentul standard pentru un chist folicular?","options":[{"id":"A","text":"În cazul chisturilor foliculare de mari dimensiuni, aspectul poate fi aparent multilocular."},{"id":"B","text":"Exclusiv chiuretajul inserției chistului la nivelul coletului, cu conservarea dintelui."},{"id":"C","text":"Chistectomie și odontectomia dintelui inclus sau semiinclus asociat."},{"id":"D","text":"Marsupializarea ca unică metodă terapeutică pentru a reduce riscul de fractură."},{"id":"E","text":"Decompresia chistului, urmată de monitorizare radiologică pe termen lung."}],"correct":["C"],"pages":[639],"source":"set-2"},{"id":"set2-1ItIef2i","fingerprint":"e4ca06a7db47a96a","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt afirmațiile corecte referitoare la tratamentul chisturilor foliculare de mari dimensiuni?","options":[{"id":"A","text":"Chisturile extinse spre bazilara mandibulei pot necesita un abord cervical pentru chistectomie."},{"id":"B","text":"Recidivele sunt frecvente, chiar și după îndepărtarea completă a chistului."},{"id":"C","text":"Se poate practica decompresia sau marsupializarea într-o primă etapă, urmată de chistectomie."},{"id":"D","text":"Marsupializarea singulară este suficientă pentru a elimina riscul de infecție."},{"id":"E","text":"La copii și preadolescenți, marsupializarea este singura alternativă viabilă."}],"correct":["A","C"],"pages":[639],"source":"set-2"},{"id":"set2-zlQ-maVd","fingerprint":"d4668c1f6694448a","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Care dintre următoarele reprezintă un risc rar de transformare a epiteliului unui chist folicular?","options":[{"id":"A","text":"Transformare în chist odontogen adenomatoid."},{"id":"B","text":"Transformare în fibrom ameloblastic."},{"id":"C","text":"Transformare în carcinom spinocelular."},{"id":"D","text":"Transformare în carcinom mucoepidermoid."},{"id":"E","text":"Transformare în ameloblastom."}],"correct":["C"],"pages":[639],"source":"set-2"},{"id":"set2-zFXiXWrM","fingerprint":"1c074617e87c28d2","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Care dintre următoarele afirmații descrie particularitățile patogenice și de dezvoltare ale keratochistului odontogen?","options":[{"id":"A","text":"Keratochistul odontogen primordial se dezvoltă în locul unui dinte, derivând din resturile Serres sau celulele bazale ale epiteliului oral."},{"id":"B","text":"Mecanismul principal de dezvoltare este reprezentat de creșterea presiunii osmotice intrachistice."},{"id":"C","text":"Keratochistul odontogen dentiger se dezvoltă în locul unui dinte și derivă din lamina dentară."},{"id":"D","text":"Forma dentigeră are un caracter recidivant mult mai marcat comparativ cu forma primordială."},{"id":"E","text":"Forma primordială derivă din epiteliul adamantin redus și se dezvoltă în jurul unui dinte."}],"correct":["A"],"pages":[637],"source":"set-2"},{"id":"set2-MyjCuPnX","fingerprint":"28d03047e1ac7685","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt caracteristicile clinice și evolutive specifice keratochistului odontogen?","options":[{"id":"A","text":"Induce tulburări senzitive în teritoriul nervului alveolar inferior prin comprimarea acestuia spre bazilara mandibulei."},{"id":"B","text":"Extinderea se produce predominant în plan mezio-distal, de-a lungul medularei osoase."},{"id":"C","text":"Determină mobilitatea dinților adiacenți și resorbția progresivă a rădăcinilor acestora."},{"id":"D","text":"Perforarea peretelui chistic și eliberarea conținutului bogat în keratină provoacă o reacție inflamatorie marcată de durere și edem."},{"id":"E","text":"Extinderea se realizează predominant în plan vestibulo-lingual, asociată cu liză osoasă corticală precoce."}],"correct":["B","C","D"],"pages":[638],"source":"set-2"},{"id":"set2-lzOmQSre","fingerprint":"55abe692b3ff0a1f","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care dintre următorii factori sunt asociați cu o rată crescută de recidivă a keratochisturilor odontogene?","options":[{"id":"A","text":"Apartenența la forma anatomo-clinică dentigeră."},{"id":"B","text":"Dimensiunile reduse ale leziunilor și caracterul unilocular."},{"id":"C","text":"Forma anatomo-clinică primordială."},{"id":"D","text":"Eroziunea corticalelor osoase."},{"id":"E","text":"Neîndepărtarea chistului monobloc."}],"correct":["C","D","E"],"pages":[638],"source":"set-2"},{"id":"set2-yS2ji_et","fingerprint":"8e76c84889143722","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Diagnosticul diferențial radiologic pentru un keratochist odontogen primordial multilocular include următoarele afecțiuni:","options":[{"id":"A","text":"Ameloblastomul."},{"id":"B","text":"Chistul rezidual."},{"id":"C","text":"Malformațiile arterio-venoase osoase centrale."},{"id":"D","text":"Mixomul odontogen."},{"id":"E","text":"Cavitatea osoasă idiopatică."}],"correct":["A","C","D"],"pages":[637],"source":"set-2"},{"id":"set2-dma1d1-r","fingerprint":"f88963b280026423","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care dintre următoarele particularități terapeutice și prognostice se aplică în managementul keratochistului odontogen?","options":[{"id":"A","text":"Marsupializarea este strict contraindicată la formele dentigere din cauza riscului iminent de malignizare."},{"id":"B","text":"Pentru keratochisturile primordiale se indică extirparea unei porțiuni de mucoasă alveolară hiperkeratinizată."},{"id":"C","text":"Rezecția osoasă marginală sau segmentară se indică în cazul recidivelor multiple survenite după chistectomie."},{"id":"D","text":"Nervul alveolar inferior necesită rezecție frecventă deoarece prezintă infiltrare tumorală precoce."},{"id":"E","text":"Chistectomia efectuată ca primă intenție curativă reduce riscul de recidivă sub pragul de 10%."}],"correct":["B","C"],"pages":[638],"source":"set-2"},{"id":"set2-4XnF06Hd","fingerprint":"4eb0ec6e7bc5faef","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Care dintre următoarele afirmații descrie caracteristicile etiopatogenice și topografice ale chistului folicular?","options":[{"id":"A","text":"Afectează cu predilecție femeile de vârstă mijlocie, manifestându-se printr-o simptomatologie dureroasă precoce."},{"id":"B","text":"Se formează exclusiv prin acumularea de lichid între epiteliul adamantin redus și țesutul osos alveolar."},{"id":"C","text":"Constituie aproximativ 20% din totalul chisturilor de dezvoltare, fiind cel mai frecvent chist odontogen al maxilarelor."},{"id":"D","text":"Varianta cu patogenie inflamatorie este asociată exclusiv cu procesele infecțioase acute ale incisivilor centrali."},{"id":"E","text":"Atașamentul leziunii se realizează la nivelul joncțiunii smalț-cement a unui dinte neerupt, a cărui coroană o înconjoară."}],"correct":["E"],"pages":[638],"source":"set-2"},{"id":"set2-jfxuUw4m","fingerprint":"479677305cd1ebbc","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt caracteristicile variantelor radiologice atipice ale chistului folicular?","options":[{"id":"A","text":"Varianta cu extensie laterală interesează porțiunea distală a unui molar de minte inferior semiinclus, extinzându-se spre ramul mandibular."},{"id":"B","text":"Varianta circumferențială respectă cu strictețe joncțiunea amelo-dentinară a coletului dentar."},{"id":"C","text":"Varianta cu extensie vestibulară generează o imagine de radiotransparență uniloculară suprapusă peste bifurcația rădăcinilor dintelui."},{"id":"D","text":"Chistul vestibular de bifurcație se localizează exclusiv la nivelul caninilor maxilari incluși."},{"id":"E","text":"Aspectul radiologic aparent multilocular al formelor de mari dimensiuni este dat de prezența unor trabecule osoase restante."}],"correct":["A","C","E"],"pages":[639],"source":"set-2"},{"id":"set2-q-gVWajD","fingerprint":"b11bd6493400ce89","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Ce aspecte definesc evoluția, complicațiile și diagnosticul diferențial asociate chistului folicular?","options":[{"id":"A","text":"Suprainfectarea chistului de la un proces periapical determină o delimitare radiologică mult mai netă a marginilor osoase."},{"id":"B","text":"Epiteliul chistic prezintă un risc moderat de transformare în ameloblastom."},{"id":"C","text":"Degenerarea malignă a celulelor glandulare mucoase parietale evoluează invariabil spre carcinom spinocelular."},{"id":"D","text":"Diagnosticul diferențial pentru localizările din sectorul anterior include chistul sau tumora odontogenă adenomatoidă."},{"id":"E","text":"Formațiunile de mari dimensiuni care deformează părțile moi sugerează adesea un keratochist odontogen dentiger sau un ameloblastom."}],"correct":["B","D","E"],"pages":[639],"source":"set-2"},{"id":"set2-4UBeDVG6","fingerprint":"cfff6af370760bdd","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt principiile terapeutice chirurgicale aplicabile în managementul chistului folicular?","options":[{"id":"A","text":"Conservarea dintelui asociat după efectuarea chistectomiei reprezintă o intervenție indicată și sigură pentru pacienții tineri."},{"id":"B","text":"Marsupializarea utilizată ca tehnică singulară previne riscul de fractură a maxilarelor și elimină complicațiile infecțioase."},{"id":"C","text":"Tratamentul de bază presupune efectuarea chistectomiei asociate cu odontectomia dintelui semiinclus sau inclus."},{"id":"D","text":"Chisturile de mari dimensiuni care se extind spre bazilara mandibulei se abordează exclusiv prin rezecție osoasă marginală."},{"id":"E","text":"În cazul leziunilor voluminoase, se poate recurge inițial la decompresie pentru a obține o reducere progresivă a volumului."}],"correct":["A","C","E"],"pages":[639],"source":"set-2"},{"id":"set2-a5uHOE1-","fingerprint":"0b46cd92553ce422","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Un pacient adolescent de sex masculin se prezintă pentru un examen radiologic de rutină în urma căruia se observă o radiotransparență uniloculară suprapusă peste bifurcația rădăcinilor unui molar de minte inferior semiinclus, generată prin împingerea leziunii spre vestibular. Care este entitatea clinică specifică ce corespunde acestei descrieri?","options":[{"id":"A","text":"Keratochistul odontogen dentiger."},{"id":"B","text":"Fibromul ameloblastic chistic."},{"id":"C","text":"Tumora odontogenă adenomatoidă."},{"id":"D","text":"Varianta circumferențială a chistului periapical."},{"id":"E","text":"Chistul vestibular de bifurcație (chistul paradentar)."}],"correct":["E"],"pages":[638],"source":"set-2"},{"id":"set2-tn6XXj6t","fingerprint":"a2f10750d5e2154c","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt particularitățile patogenice și de origine ale keratochistului odontogen?","options":[{"id":"A","text":"Keratochistul odontogen dentiger se dezvoltă în locul unui dinte și prezintă o rată crescută de recidivă."},{"id":"B","text":"Keratochistul odontogen dentiger are ca punct de plecare epiteliul adamantin redus."},{"id":"C","text":"Afecțiunea derivă din lamina dentară și este considerată de anumiți autori o tumoră benignă chistică."},{"id":"D","text":"Forma primordială derivă din resturile Serres sau din celulele bazale ale epiteliului oral."},{"id":"E","text":"Creșterea presiunii osmotice intrachistice reprezintă mecanismul principal de dezvoltare a leziunii."}],"correct":["B","C","D"],"pages":[636,637],"source":"set-2"},{"id":"set2-Z5sEI4dF","fingerprint":"ab1ef91686326b1f","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Care afirmație descrie cel mai precis tiparul de extindere și liza osoasă în cazul keratochistului odontogen?","options":[{"id":"A","text":"Leziunea are tendința de a se extinde mai mult în plan mezio-distal, de-a lungul medularei osoase."},{"id":"B","text":"La nivelul maxilarului, distrucția corticalei osoase se manifestă în special spre palatinal."},{"id":"C","text":"Compresiunea pachetului vasculo-nervos alveolar inferior pe bazilara mandibulei induce frecvent tulburări senzitive în teritoriu."},{"id":"D","text":"La mandibulă, în zona laterală, liza corticalelor osoase se produce cu predilecție spre vestibular."},{"id":"E","text":"Extinderea leziunii se realizează predominant în sens vestibulo-lingual, liza medularei osoase apărând tardiv."}],"correct":["A"],"pages":[636,637],"source":"set-2"},{"id":"set2-e-P4_O6X","fingerprint":"3f7ab070e04d8adc","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Ce caracteristici sunt asociate cu prezența și dezvoltarea keratochisturilor odontogene?","options":[{"id":"A","text":"Aceste leziuni constituie majoritatea absolută a chisturilor odontogene diagnosticate în practica curentă."},{"id":"B","text":"Manifestările din cadrul sindromului Gorlin includ prezența unor keratochisturi multiple, prezente simultan sau apărând în diferite localizări, la intervale de câțiva ani."},{"id":"C","text":"Evoluția leziunilor determină apariția mobilității dinților adiacenți, asociată cu resorbția progresivă a rădăcinilor dentare."},{"id":"D","text":"Perforarea peretelui chistic permite extravazarea unui conținut bogat în mucină, declanșând durere și edem."},{"id":"E","text":"Apariția lor la copii este observată de obicei în contextul sindromului nevic bazocelular, cunoscut și ca sindromul Gorlin."}],"correct":["B","C","E"],"pages":[636,637],"source":"set-2"},{"id":"set2--ZYddXRA","fingerprint":"fc3c2b22687987c4","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt aspectele radiologice caracteristice keratochisturilor odontogene?","options":[{"id":"A","text":"Aspectul radiologic al keratochistului odontogen dentiger îl distinge clar și precis de un chist dentiger simplu."},{"id":"B","text":"Aspectul multilocular este caracteristic în mod particular leziunilor situate la nivelul molarului trei inferior."},{"id":"C","text":"Leziunile apar ca zone radiotransparente cu contur net, prezentând uneori o corticalizare perilezională."},{"id":"D","text":"Resorbția radiculară a dinților vecini erupți se observă frecvent, reprezentând însă o modificare nepatognomonică."},{"id":"E","text":"Prezența parțială a unui dinte neerupt în interiorul leziunii definește tabloul radiologic al keratochistului odontogen primordial."}],"correct":["B","C","D"],"pages":[636,637],"source":"set-2"},{"id":"set2-KjYvs2I7","fingerprint":"170cd4a399929b0f","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Care afirmație referitoare la incidența, vârsta de apariție și localizarea predilectă a keratochistului odontogen este exactă?","options":[{"id":"A","text":"Afecțiunea are o ușoară predilecție pentru sexul feminin în rândul adolescenților și tinerilor."},{"id":"B","text":"În localizarea maxilară, afecțiunea se dezvoltă exclusiv în regiunea molarului trei, respectând complet zona frontală."},{"id":"C","text":"Sediul anatomic de elecție este situat la nivelul mandibulei, mai ales în regiunea molarului de minte."},{"id":"D","text":"Ponderea acestor chisturi se ridică la aproximativ 20-30% din cazuistica formațiunilor chistice odontogene."},{"id":"E","text":"Maxilarul superior reprezintă sediul principal de dezvoltare, în special în regiunea incisivilor centrali."}],"correct":["C"],"pages":[636,637],"source":"set-2"},{"id":"set2-8VaytcLK","fingerprint":"e6b8bc8febba7e29","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt factorii care cresc riscul de recidivă al keratochistului odontogen?","options":[{"id":"A","text":"Neîndepărtarea chistului monobloc."},{"id":"B","text":"Varianta clinico-anatomică de keratochist odontogen dentiger."},{"id":"C","text":"Dimensiunile mari ale formațiunii chistice."},{"id":"D","text":"Aspectul radiologic unilocular."},{"id":"E","text":"Erodarea corticalelor osoase."}],"correct":["A","C","E"],"pages":[638],"source":"set-2"},{"id":"set2-wxBFrJwb","fingerprint":"76ffa0d9eefa230d","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt principiile anatomice și chirurgicale aplicabile în chistectomia keratochistului odontogen?","options":[{"id":"A","text":"Abordul cervical al mandibulei este necesar pentru obținerea vizibilității optime în cazul leziunilor situate la nivelul unghiului și ramului mandibular."},{"id":"B","text":"În keratochisturile primordiale se practică extirparea unei porțiuni de mucoasă alveolară hiperkeratinizată."},{"id":"C","text":"Efracționarea corticalei mandibulare impune obligatoriu extirparea unei zone de țesut din părțile moi adiacente."},{"id":"D","text":"Pachetul vasculo-nervos alveolar inferior necesită extirpare parțială deoarece este frecvent infiltrat."},{"id":"E","text":"Dinții adiacenți pot fi menținuți cu condiția unui suport osos restant adecvat și a realizării unui chiuretaj atent."}],"correct":["A","B","E"],"pages":[638],"source":"set-2"},{"id":"set2-yOsB-MA3","fingerprint":"6d99b19fed01b725","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt afecțiunile cu care se realizează diagnosticul diferențial al keratochistului odontogen primordial multilocular?","options":[{"id":"A","text":"Chistul folicular."},{"id":"B","text":"Ameloblastomul."},{"id":"C","text":"Chistul rezidual."},{"id":"D","text":"Tumora centrală cu celule gigante."},{"id":"E","text":"Malformațiile arterio-venoase osoase centrale."}],"correct":["B","D","E"],"pages":[637],"source":"set-2"},{"id":"set2-xkAFKFwQ","fingerprint":"d8ba4e9b5e69b85e","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt situațiile clinice care reprezintă indicații pentru realizarea rezecției osoase marginale sau segmentare în tratamentul keratochisturilor odontogene?","options":[{"id":"A","text":"Facilitarea erupției unui dinte inclus la nivelul procesului chistic."},{"id":"B","text":"Abordarea curativă de primă intenție pentru keratochisturile de dimensiuni relativ mici."},{"id":"C","text":"Recidivele multiple apărute ulterior unei chistectomii."},{"id":"D","text":"Existența unui keratochist primordial ce necesită îndepărtarea mucoasei alveolare hiperkeratinizate."},{"id":"E","text":"Erodarea corticalei osoase de către o leziune voluminoasă unde chiuretajul ar întrerupe continuitatea osoasă."}],"correct":["C","E"],"pages":[638],"source":"set-2"},{"id":"set2-xe6qhXtn","fingerprint":"c9b5bf5e029c2ace","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt afirmațiile adevărate privind diagnosticul diferențial al keratochistului odontogen primordial unilocular?","options":[{"id":"A","text":"Trebuie diferențiat de fibromul ameloblastic."},{"id":"B","text":"Are un aspect radiologic ce impune diagnosticul diferențial cu mixomul odontogen."},{"id":"C","text":"Se diferențiază de tumora odontogenă adenomatoidă în special pentru localizările posterioare."},{"id":"D","text":"Presupune diferențierea de cavitatea osoasă idiopatică."},{"id":"E","text":"Necesită diferențierea de chistul parodontal lateral."}],"correct":["A","D","E"],"pages":[637],"source":"set-2"},{"id":"set2-YA8YNSvU","fingerprint":"b5eb4b09f4681df7","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care dintre următoarele afirmații descriu corect patogenia și caracteristicile chistului folicular?","options":[{"id":"A","text":"Afectează cu predilecție pacienții vârstnici de sex feminin."},{"id":"B","text":"Se dezvoltă prin transformarea chistică a foliculului dentar în jurul coroanei unui dinte neerupt."},{"id":"C","text":"Structura chistică se atașează întotdeauna la joncțiunea smalț-cement a dintelui implicat."},{"id":"D","text":"Se formează prin acumularea de conținut chistic între coroana dintelui și epiteliul adamantin redus."},{"id":"E","text":"Reprezintă aproximativ 50% din chisturile de dezvoltare, fiind cel mai frecvent chist al maxilarelor."}],"correct":["B","C","D"],"pages":[638],"source":"set-2"},{"id":"set2-SieKWDR9","fingerprint":"11e9b6046e3e7081","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Referitor la variantele radiologice ale chistului folicular, care sunt afirmațiile adevărate?","options":[{"id":"A","text":"Varianta circumferențială respectă cu strictețe limitele joncțiunii amelo-dentinare a coletului dentar, fără a se extinde apical."},{"id":"B","text":"Chistul vestibular de bifurcație prezintă o localizare exclusivă la nivelul caninilor superiori incluși."},{"id":"C","text":"Varianta cu extensie laterală interesează doar porțiunea distală a unui molar de minte inferior, extinzându-se spre ramul mandibular."},{"id":"D","text":"Aspectul aparent multilocular al formelor chistice de mari dimensiuni este generat de trabecule osoase restante suprapuse peste radiotransparență."},{"id":"E","text":"Varianta cu extensie vestibulară determină o radiotransparență suprapusă peste bifurcația rădăcinilor, fiind numită și chist paradentar."}],"correct":["C","D","E"],"pages":[639],"source":"set-2"},{"id":"set2-REtcMUPP","fingerprint":"2f1a6f2a3304cfdc","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"O formațiune radiotransparentă localizată la nivelul maxilarelor, având un aspect inițial de chist dentiger, ajunge la dimensiuni considerabile și deformează masiv părțile moi. Care sunt diagnosticele principale care trebuie luate în considerare în această situație clinică?","options":[{"id":"A","text":"Osteomielita cronică sclerozantă și chistul osos simplu."},{"id":"B","text":"Keratochistul odontogen dentiger și ameloblastomul."},{"id":"C","text":"Granulomul periapical gigant și chistul radicular suprainfectat."},{"id":"D","text":"Fibromul osificant și displazia cimento-osoasă floridă."},{"id":"E","text":"Mixomul odontogen și tumora calcificantă epitelială odontogenă."}],"correct":["B"],"pages":[638],"source":"set-2"},{"id":"set2-l8E11VVI","fingerprint":"d74856109ecc8b44","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt factorii inflamatorii locali care pot contribui, ca excepție de la etiologia strictă de dezvoltare, la apariția unui chist folicular?","options":[{"id":"A","text":"Inflamațiile periapicale cronice ale unui dinte decidual supraiacent."},{"id":"B","text":"Episoadele repetate de pericoronarită ale unui dinte semiinclus."},{"id":"C","text":"Parodontita marginală cronică generalizată avansată."},{"id":"D","text":"Traumatismele ocluzale cronice primare asociate cu parafuncții."},{"id":"E","text":"Granuloamele de corp străin apărute post-extracțional la nivelul alveolei."}],"correct":["A","B"],"pages":[638],"source":"set-2"},{"id":"set2-MrG797Yj","fingerprint":"a6d3ca0ded03715a","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Ce consecințe anatomice locale poate produce un chist folicular în evoluția sa intraosoasă asupra structurilor dentare?","options":[{"id":"A","text":"Deplasarea semnificativă a dintelui de la nivelul căruia derivă formațiunea chistică."},{"id":"B","text":"Inducerea resorbției radiculare a dinților învecinați."},{"id":"C","text":"Anchiloza dento-alveolară ireversibilă a dinților adiacenți."},{"id":"D","text":"Mineralizarea accelerată prin depuneri de dentină secundară a canalelor radiculare vecine."},{"id":"E","text":"Deplasarea dinților adiacenți cu care intră în contact direct."}],"correct":["A","B","E"],"pages":[639],"source":"set-2"},{"id":"set2-CmCnJAiE","fingerprint":"564009507c6302fa","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care dintre următoarele entități patologice sunt incluse în diagnosticul diferențial al chistului folicular?","options":[{"id":"A","text":"Fibromul ameloblastic"},{"id":"B","text":"Carcinomul mucoepidermoid"},{"id":"C","text":"Ameloblastomul"},{"id":"D","text":"Keratochistul odontogen dentiger"},{"id":"E","text":"Carcinomul spinocelular"}],"correct":["A","C","D"],"pages":[639],"source":"set-2"},{"id":"set2-29H2ZpVQ","fingerprint":"fa16a314e5a7bb03","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la conduita terapeutică generală a chisturilor foliculare?","options":[{"id":"A","text":"Chisturile foliculare cu extindere masivă spre bazilara mandibulei pot necesita o chistectomie cu abord cervical."},{"id":"B","text":"Recidivele sunt frecvente și recurente chiar și în cazul îndepărtării complete a peretelui chistic."},{"id":"C","text":"Tratamentul chirurgical impune sacrificiul dintelui asociat în toate situațiile clinice, fără excepții."},{"id":"D","text":"Decompresia sau marsupializarea se indică drept primă etapă terapeutică pentru chisturile de mari dimensiuni."},{"id":"E","text":"Chistectomia cu prezervarea dinților asociați reprezintă o procedură de elecție pentru copii și preadolescenți."}],"correct":["A","D","E"],"pages":[639],"source":"set-2"},{"id":"set2-8NBknDKq","fingerprint":"e709f5cbcc21808d","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Care este afirmația care descrie cu exactitate potențialul evolutiv și riscul de transformare al chistului folicular?","options":[{"id":"A","text":"Leziunea evoluează constant către tumora odontogenă adenomatoidă în cazul localizărilor posterioare."},{"id":"B","text":"Prezintă un risc moderat de transformare în ameloblastom."},{"id":"C","text":"Chistul folicular suferă o metaplazie constantă transformându-se în fibrom ameloblastic."},{"id":"D","text":"Epiteliul chistic prezintă un grad înalt de transformare în carcinom spinocelular, necesitând profilaxie oncologică."},{"id":"E","text":"Celulele glandulare mucoase suferă în mod frecvent o transformare malignă în carcinom mucoepidermoid."}],"correct":["B"],"pages":[639],"source":"set-2"},{"id":"set2-jL961hZJ","fingerprint":"381f78b4498c5e83","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt caracteristicile procedurilor de decompresie și marsupializare utilizate în managementul chisturilor foliculare?","options":[{"id":"A","text":"Sunt contraindicate ca etapă preliminară în abordarea chisturilor masive din cauza riscului hemoragic."},{"id":"B","text":"Scopul principal al acestor tehnici este inducerea expansiunii volumetrice a leziunii."},{"id":"C","text":"Decompresia presupune crearea unei mici fenestrații prin puncție sau incizie, necesitând menținerea sa deschisă prin dispozitive."},{"id":"D","text":"Marsupializarea aplicată ca procedură chirurgicală unică nu va reduce riscul de apariție a infecției."},{"id":"E","text":"După diminuarea volumului chistic, tratamentul este completat printr-o etapă chirurgicală de chistectomie."}],"correct":["C","D","E"],"pages":[639],"source":"set-2"},{"id":"set2-qFKhyTl_","fingerprint":"ef68cff38a1e3e67","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la patogenia și evoluția chistului radicular?","options":[{"id":"A","text":"Prezintă trei forme anatomo-clinice în funcție de localizare și evoluție: chistul periapical, chistul radicular lateral și chistul rezidual."},{"id":"B","text":"Reprezintă cel mai frecvent chist din patologia oaselor maxilare, fiind un chist inflamator endoosos."},{"id":"C","text":"Se dezvoltă exclusiv prin transformarea chistică a resturilor epiteliale Malassez, restul structurilor epiteliale de vecinătate nefiind implicate."},{"id":"D","text":"Testele de vitalitate ale dinților cauzali sunt întotdeauna negative, având în vedere prezența gangrenei pulpare."},{"id":"E","text":"Evoluția procesului patologic debutează cu gangrena pulpară, urmată de pulpită și extinderea infecției prin foramenul apical."}],"correct":["A","B","D"],"pages":[640],"source":"set-2"},{"id":"set2-Z-FFXMhe","fingerprint":"569cecce24ae73c1","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"În evoluția clinică a chistului periapical, liza corticalei osoase determină la palpare un semn clinic specific, asociat cu o consistență particulară. Care dintre următoarele afirmații descrie corect acest aspect?","options":[{"id":"A","text":"Se decelează semnul lui Vincent, tradus clinic prin anestezia teritoriului de inervație al nervului alveolar inferior."},{"id":"B","text":"Apare o deformare asimetrică a conturului facial, asociată cu prezența unor crepitații gazoase la nivelul spațiilor fasciale primare."},{"id":"C","text":"Fluctuența apare precoce, fiind primul semn clinic evident decelabil la palpare, chiar înaintea subțierii corticalei osoase."},{"id":"D","text":"Palparea este complet nedureroasă și se percepe o consistență dură, lemnoasă a osului subiacent."},{"id":"E","text":"Se percepe o consistență de „minge de celuloid” sau „coajă de ou spart”, fenomen clinic cunoscut sub denumirea de semnul lui Dupuytren."}],"correct":["E"],"pages":[640],"source":"set-2"},{"id":"set2-4LrpVyl7","fingerprint":"3ff701e0f2e56300","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt caracteristicile imagistice și aspectele ce țin de diagnosticul diferențial al chistului periapical?","options":[{"id":"A","text":"Diagnosticul diferențial radiologic între un chist periapical de mici dimensiuni și un granulom periapical se realizează cu ușurință prin simpla identificare a conturului radioopac."},{"id":"B","text":"Prezența conturului radioopac periferic indică o liză activă și fulminantă a corticalei osoase, fără fenomene de scleroză reactivă."},{"id":"C","text":"Apexurile dinților implicați sunt incluse în cavitatea chistică, aceste structuri radiculare putând prezenta uneori fenomene de resorbție."},{"id":"D","text":"Entitatea cunoscută sub denumirea de „chist median mandibular” reprezintă de cele mai multe ori expresia clinică și radiologică a unui chist radicular dezvoltat la nivelul dinților frontali inferiori."},{"id":"E","text":"Radiologic, formațiunea se prezintă sub forma unei radiotransparențe periapicale bine delimitate, care deformează și șterge conturul laminei dura în porțiunea apicală."}],"correct":["C","D","E"],"pages":[640],"source":"set-2"},{"id":"set2-zUO5Icad","fingerprint":"7add36e397028eb4","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"În conduita terapeutică indicată pentru chisturile radiculare de dimensiuni mici și medii, care sunt atitudinile corecte în funcție de parametrii dintelui cauzal?","options":[{"id":"A","text":"În prezența unei distrucții coronare masive, ce determină irecuperabilitatea protetică a dintelui, se indică extracția dentară urmată de chistectomie prin alveola postextracțională."},{"id":"B","text":"Dacă accesul asigurat prin alveola postextracțională este insuficient pentru îndepărtarea completă a chistului, procedura se va continua prin realizarea chistectomiei pe cale vestibulară."},{"id":"C","text":"Includerea a mai mult de o treime din apex în interiorul formațiunii chistice reprezintă o indicație absolută pentru tratamentul conservator urmat de marsupializarea exclusivă a leziunii."},{"id":"D","text":"Gestul terapeutic inițial și obligatoriu pentru orice chist periapical, indiferent de starea parodontală a dintelui, constă în extracția sistematică a acestuia."},{"id":"E","text":"Dacă dintele este recuperabil, are o implantare bună și mai puțin de o treime din rădăcină este inclusă în chist, se practică chistectomia cu rezecție apicală și tratament endodontic intraoperator."}],"correct":["A","B","E"],"pages":[641],"source":"set-2"},{"id":"set2-ZjRgXqhq","fingerprint":"6d3ecc3d215c6f50","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Pentru chisturile radiculare de mari dimensiuni localizate la maxilar, care prezintă o extensie importantă în sinusul maxilar dar mențin o separație osoasă minimă între peretele chistic și mucoasa sinuzală, care este atitudinea terapeutică recomandată în privința sinusului?","options":[{"id":"A","text":"Este necesară excizia în bloc a chistului periapical împreună cu membrana sinuzală adiacentă pentru a asigura eradicarea patologiei."},{"id":"B","text":"Se optează exclusiv pentru marsupializarea formațiunii chistice în fosele nazale, tratamentul dintelui cauzal fiind contraindicat."},{"id":"C","text":"Nu este necesară efectuarea curei radicale a sinusului maxilar."},{"id":"D","text":"Se practică obligatoriu puncția sinuzală diagnostică, urmată de chistectomie exclusiv prin abord palatinal."},{"id":"E","text":"Se impune întotdeauna cura radicală a sinusului maxilar, având în vedere proximitatea marcată a leziunii osoase."}],"correct":["C"],"pages":[641],"source":"set-2"},{"id":"set2-agqJ6cj2","fingerprint":"2290b3202c390c54","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Care este originea patogenică a chistului radicular lateral?","options":[{"id":"A","text":"Canalele pulpare aberante situate la nivelul suprafeței laterale a rădăcinii dintelui"},{"id":"B","text":"Resturile epiteliale Serres din porțiunea de gingie fixă"},{"id":"C","text":"Degenerescența chistică a laminei dentare"},{"id":"D","text":"Resturile epiteliale Malassez din ligamentul parodontal"},{"id":"E","text":"Proliferarea epiteliului redus al smalțului"}],"correct":["A"],"pages":[641],"source":"set-2"},{"id":"set2-U31up_zR","fingerprint":"2d7ce80a11e93ddf","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Cu ce afecțiuni se impune realizarea diagnosticului diferențial în cazul unui chist radicular lateral?","options":[{"id":"A","text":"Keratochistul odontogen primordial"},{"id":"B","text":"Parodontopatia marginală cronică profundă"},{"id":"C","text":"Chistul dentiger"},{"id":"D","text":"Tumora odontogenă adenomatoidă"},{"id":"E","text":"Chistul parodontal lateral"}],"correct":["A","B","E"],"pages":[641],"source":"set-2"},{"id":"set2-9hiFAkay","fingerprint":"1229532995117d30","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt caracteristicile clinico-radiologice și particularitățile terapeutice specifice chistului radicular lateral?","options":[{"id":"A","text":"Examenul radiologic evidențiază o radiotransparență de mici dimensiuni cu localizare radiculară laterală."},{"id":"B","text":"Evoluția chistului conduce la erodarea limbusului alveolar interdentar, compromițând implantarea dintelui."},{"id":"C","text":"Tratamentul chirurgical conservator presupune rezecția apicală a dintelui cauzal."},{"id":"D","text":"Tehnica operatorie de elecție constă în marsupializarea formațiunii chistice."},{"id":"E","text":"Radiotransparența este situată cel mai frecvent la nivelul limbusului osos interdentar."}],"correct":["A","B","E"],"pages":[641],"source":"set-2"},{"id":"set2-hcC1Dh6z","fingerprint":"b0c7f0514ddedaf3","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt factorii care pot determina eșecul tratamentului endodontic, favorizând apariția sau menținerea unui chist rezidual?","options":[{"id":"A","text":"Obturația de canal cu depășire, care acționează ca un factor iritativ."},{"id":"B","text":"Indicația eronată în raport cu dimensiunile chistului."},{"id":"C","text":"Chiuretarea riguroasă a alveolei postextracționale."},{"id":"D","text":"Sigilarea etanșă a suprafeței de secțiune a rădăcinii."},{"id":"E","text":"Obturația de canal deficitară, ce permite permeabilitatea pentru germenii din cavitatea orală."}],"correct":["A","B","E"],"pages":[642],"source":"set-2"},{"id":"set2-ajNmQWuk","fingerprint":"414e5feae19b5fb4","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Cu ce entități patologice se realizează diagnosticul diferențial al chistului rezidual apărut după extracția dentară?","options":[{"id":"A","text":"Chistul osos anevrismal."},{"id":"B","text":"Keratochistul odontogen primordial."},{"id":"C","text":"Chistul osos traumatic."},{"id":"D","text":"Chistul periapical asociat unui dinte neobturat pe canal."},{"id":"E","text":"Chistul dentiger de erupție."}],"correct":["A","B","C"],"pages":[642],"source":"set-2"},{"id":"set2-v81IGG3p","fingerprint":"d525ddf52612be44","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Care este atitudinea terapeutică indicată în cazul unui chist rezidual menținut în urma unui tratament endodontic eșuat?","options":[{"id":"A","text":"Chiuretarea alveolei postextracționale pentru a induce vindecarea osoasă."},{"id":"B","text":"Extracția dintelui fără necesitatea abordării formațiunii chistice apicale."},{"id":"C","text":"Chistectomia cu rezecție apicală și sigilarea suprafeței de secțiune a rădăcinii."},{"id":"D","text":"Chistectomia exclusivă prin abord oral."},{"id":"E","text":"Realizarea unei obturații de canal cu depășire intenționată a apexului."}],"correct":["C"],"pages":[642],"source":"set-2"},{"id":"set2-ApE60SgM","fingerprint":"13443f77c688a4de","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care dintre următoarele afirmații descriu corect aspectele clinice, patogenice și radiologice ale chistului rezidual?","options":[{"id":"A","text":"Diagnosticul diferențial pentru forma apărută după tratament endodontic se realizează cu chistul periapical."},{"id":"B","text":"După extracția dentară, aspectul radiologic apare la nivelul unei creste edentate anterior vindecării osoase a alveolei."},{"id":"C","text":"Clasic, termenul definește un chist restant după o extracție dentară în care nu s-a realizat chiuretarea alveolei."},{"id":"D","text":"Chistul rezidual după tratament endodontic are aspectul radiologic al unui chist periapical la un dinte cu obturație de canal."},{"id":"E","text":"În prezent, conceptul de chist rezidual exclude patologiile apărute după tratamente endodontice, limitându-se la extracții."}],"correct":["A","C","D"],"pages":[642],"source":"set-2"},{"id":"set2-rY4tQ7S4","fingerprint":"4d2740905ce6166d","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Care este tratamentul de elecție recomandat pentru ameloblastomul solid sau multichistic localizat în porțiunea orizontală a mandibulei?","options":[{"id":"A","text":"Radioterapia în doză curativă, utilizată pentru a preveni transformarea în carcinom ameloblastic."},{"id":"B","text":"Enucleerea simplă, având o rată de recidivă postoperatorie acceptabilă de sub 20%."},{"id":"C","text":"Chiuretajul tumoral urmat de radioterapie, tumora fiind considerată extrem de radiosensibilă."},{"id":"D","text":"Rezecția marginală cu asigurarea unor margini osoase libere de cel puțin 1-1,5 cm."},{"id":"E","text":"Rezecția segmentară, indicată obligatoriu indiferent de localizare datorită caracterului extrem de invaziv."}],"correct":["D"],"pages":[643],"source":"set-2"},{"id":"set2-B3cwAK_i","fingerprint":"97621d6f41491200","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care dintre următoarele reprezintă origini histologice posibile ale ameloblastomului?","options":[{"id":"A","text":"Epiteliul respirator al mucoasei intrasinusale."},{"id":"B","text":"Epiteliul unui chist odontogen derivat din resturile Malassez."},{"id":"C","text":"Resturile laminei dentare Serres."},{"id":"D","text":"Țesutul osos medular adiacent foliculului dentar."},{"id":"E","text":"Stratul bazal al mucoasei orale."}],"correct":["B","C","E"],"pages":[642],"source":"set-2"},{"id":"set2-o53BoZR7","fingerprint":"8fe18edc93564660","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Ce caracteristici clinico-radiologice sunt asociate ameloblastomului intraosos solid sau multichistic?","options":[{"id":"A","text":"Este prezent fenomenul de resorbție radiculară a dinților situați în imediata vecinătate."},{"id":"B","text":"Tumora include frecvent prezența unui dinte inclus intraosos la nivelul leziunii."},{"id":"C","text":"Durerea și paresteziile apar constant ca simptome primare în stadiile incipiente."},{"id":"D","text":"Formațiunea tumorală prezintă o tendință generală marcată de a invada părțile moi post-efracționare corticală."},{"id":"E","text":"Loculațiile de mari dimensiuni conferă radiografic un aspect comparat cu „baloanele de săpun”."}],"correct":["A","B","E"],"pages":[642],"source":"set-2"},{"id":"set2-fPjrvD48","fingerprint":"87c47762279e4ece","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Cu care dintre următoarele entități patologice se poate realiza diagnosticul diferențial radiologic al ameloblastomului solid cu aspect multilocular?","options":[{"id":"A","text":"Chistul osos anevrismal."},{"id":"B","text":"Tumorile neodontogene osteogene."},{"id":"C","text":"Keratochistul odontogen."},{"id":"D","text":"Angioamele endoosoase."},{"id":"E","text":"Carcinomul ameloblastic."}],"correct":["A","C","D"],"pages":[643],"source":"set-2"},{"id":"set2-F82RmFjY","fingerprint":"a6d144f832da8eae","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Care afirmație descrie cel mai exact comportamentul evolutiv, riscul de recidivă și potențialul de metastazare al ameloblastomului?","options":[{"id":"A","text":"Rata de recidivă consecutivă rezecției marginale atinge un prag procentual de 50-90%."},{"id":"B","text":"Transformarea în carcinom ameloblastic apare frecvent ca o complicație directă a rezecției marginale repetate."},{"id":"C","text":"Metastazarea în ganglionii loco-regionali implică o transformare malignă prealabilă obligatorie."},{"id":"D","text":"Recidivele postoperatorii sunt limitate exclusiv la primii 5 ani, după care survine vindecarea definitivă."},{"id":"E","text":"Tumora este capabilă să metastazeze în alte structuri osoase chiar și menținându-și caracterul histologic benign."}],"correct":["E"],"pages":[643],"source":"set-2"},{"id":"set2-hX0fDMGp","fingerprint":"f455ab224532917c","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Ce particularități epidemiologice și topografice definesc evoluția ameloblastomului solid sau multichistic?","options":[{"id":"A","text":"La mandibulă, formațiunea prezintă afinitate maximă pentru zona molarului trei și ramul mandibular."},{"id":"B","text":"Incidența la sexul masculin este net superioară raportat la sexul feminin."},{"id":"C","text":"Dezvoltarea leziunii este relativ rară la tineri aflați în intervalul de vârstă 10-19 ani."},{"id":"D","text":"Prezența sa la nivel maxilar este extrem de frecventă și predomină în segmentele anterioare."},{"id":"E","text":"Apariția tumorii este considerată excepțională la copii cu vârsta sub 10 ani."}],"correct":["A","C","E"],"pages":[642],"source":"set-2"},{"id":"set2-zyFKQUfF","fingerprint":"588aeca95003024f","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care dintre următoarele caracteristici clinice și epidemiologice sunt asociate cu ameloblastomul unichistic?","options":[{"id":"A","text":"Evoluția sa este caracterizată frecvent de apariția paresteziei în teritoriul nervului alveolar inferior."},{"id":"B","text":"Apare cu o frecvență crescută la pacienții tineri."},{"id":"C","text":"În stadiile avansate de evoluție produce deformarea corticalelor osoase."},{"id":"D","text":"Se localizează predominant la nivelul maxilarului, în special în regiunea anterioară."},{"id":"E","text":"Reprezintă aproximativ 10-15% din totalul ameloblastoamelor."}],"correct":["B","C","E"],"pages":[643],"source":"set-2"},{"id":"set2-fcvQb-Ix","fingerprint":"c036d0d83b076123","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la patogenia și aspectul radiologic al ameloblastomului unichistic?","options":[{"id":"A","text":"Modul exact de apariție a tumorii poate fi stabilit cu precizie exclusiv prin anamneză și istoricul bolii."},{"id":"B","text":"Imaginea radiologică tipică este o radiotransparență uniloculară bine delimitată."},{"id":"C","text":"Poate apărea prin transformarea tumorală benignă a epiteliului unui chist folicular."},{"id":"D","text":"Formațiunea prezintă în mod caracteristic și constant un aspect radiologic multilocular."},{"id":"E","text":"Aspectul radiologic se poate asemăna cu cel al unui keratochist odontogen primordial sau dentiger."}],"correct":["B","C","E"],"pages":[644],"source":"set-2"},{"id":"set2-kjg5GCG7","fingerprint":"e5b231d343687dea","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Care dintre următoarele afirmații descrie cel mai bine particularitățile clinice și radiologice ale ameloblastomului unichistic?","options":[{"id":"A","text":"Este diagnosticat în marea majoritate a cazurilor la pacienți vârstnici, reprezentând forma majoritară a ameloblastoamelor."},{"id":"B","text":"Aspectul radiologic constă în mod obișnuit într-o imagine multiloculară, imprecis delimitată de țesuturile adiacente."},{"id":"C","text":"Se localizează predominant în zona anterioară a maxilarului și prezintă inițial o simptomatologie algică intensă."},{"id":"D","text":"Evoluează cu deformarea corticalelor osoase, fără a asocia fenomene dureroase sau de parestezie în teritoriul nervului alveolar inferior."},{"id":"E","text":"Apariția sa este determinată exclusiv de evoluția de novo a țesutului tumoral din osul spongios."}],"correct":["D"],"pages":[643],"source":"set-2"},{"id":"set2-fnuC3ILe","fingerprint":"f5ca40f2a8e0b567","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Cu care dintre următoarele entități patologice se realizează diagnosticul diferențial al ameloblastomului unicistic pe criterii radiologice?","options":[{"id":"A","text":"Keratochistul odontogen primordial"},{"id":"B","text":"Cavitatea osoasă idiopatică"},{"id":"C","text":"Osteomielita sclerozantă focală"},{"id":"D","text":"Chistul median mandibular"},{"id":"E","text":"Granulomul eozinofil"}],"correct":["A","B","D"],"pages":[644],"source":"set-2"},{"id":"set2-8bxh_tpi","fingerprint":"d975bb6beb805373","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Care este atitudinea terapeutică recomandată în cazul unui ameloblastom unicistic care prezintă caracteristici histopatologice de formă microinvazivă?","options":[{"id":"A","text":"Chistotomia decompresivă urmată de curtaj"},{"id":"B","text":"Chimioterapia locală adjuvantă intracavitară"},{"id":"C","text":"Tratamentul identic cu cel al ameloblastomului solid sau multichistic"},{"id":"D","text":"Rezecția osoasă marginală profilactică"},{"id":"E","text":"Chistectomia simplă cu dispensarizare pe termen scurt"}],"correct":["D"],"pages":[644],"source":"set-2"},{"id":"set2-2DdqTvDy","fingerprint":"16a48788cee33b2b","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care dintre următoarele afirmații referitoare la managementul diagnostic și terapeutic al ameloblastomului unicistic sunt adevărate?","options":[{"id":"A","text":"Formele in situ impun realizarea unei rezecții osoase marginale pentru a preveni riscul crescut de recidivă."},{"id":"B","text":"Prima intenție de tratament o reprezintă chistectomia."},{"id":"C","text":"Formele invazive urmează principii de tratament identice cu cele aplicate în cazul ameloblastomului solid sau multichistic."},{"id":"D","text":"Diagnosticul de certitudine se stabilește pe criterii radiologice datorită aspectului patognomonic de radiotransparență uniloculară."},{"id":"E","text":"Riscul de recidivă în cazul ameloblastomului unicistic se situează în intervalul de 10-20%."}],"correct":["B","C","E"],"pages":[644],"source":"set-2"},{"id":"set2-_AK73lmP","fingerprint":"583fbadd75d8105c","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care dintre următoarele afirmații descriu originea și localizarea predilectă a ameloblastomului extraosos?","options":[{"id":"A","text":"Mai frecvent la nivelul maxilarului."},{"id":"B","text":"Epiteliul bazal al mucoasei orale."},{"id":"C","text":"Mucoasa gingivală linguală a dinților frontali."},{"id":"D","text":"Resturile lamei dentare (Serres)."},{"id":"E","text":"Mucoasa gingivală vestibulară a dinților laterali."}],"correct":["B","D","E"],"pages":[644],"source":"set-2"},{"id":"set2-fTqXz3Xk","fingerprint":"781627204376c39e","chapterId":"set-2","subchapterId":"set2-7.22","type":"CS","text":"Care este o caracteristică clinică sau radiologică definitorie pentru ameloblastomul extraosos?","options":[{"id":"A","text":"Prezentarea clinică este înalt specifică leziunii."},{"id":"B","text":"Evidențierea radiologică constantă a unei distrucții osoase masive."},{"id":"C","text":"Dimensiuni frecvent mai mari de 1,5 cm."},{"id":"D","text":"Mucoasa acoperitoare este aparent intactă."},{"id":"E","text":"Prezența durerii acute la palpare."}],"correct":["D"],"pages":[644],"source":"set-2"},{"id":"set2-mEuf60YX","fingerprint":"171e99dbf50c3906","chapterId":"set-2","subchapterId":"set2-7.22","type":"CM","text":"Care sunt afirmațiile descriind corect diagnosticul diferențial și tratamentul ameloblastomului extraosos?","options":[{"id":"A","text":"Rata de recidivă post-tratament este ridicată din cauza caracterului invaziv extrem."},{"id":"B","text":"Diagnosticul diferențial include hiperplaziile epulis-like."},{"id":"C","text":"Diagnosticul diferențial se realizează cu forme de debut ale tumorilor maligne gingivale."},{"id":"D","text":"Tratamentul constă în extirparea leziunii, fără includerea țesuturilor adiacente."},{"id":"E","text":"Fibroamele reprezintă tumori benigne gingivale cu care se face diagnosticul diferențial."}],"correct":["B","C","E"],"pages":[644],"source":"set-2"}];
